@Serializable
enum class ParticipantRole {
    @SerialName("Owner")
    Owner,
    @SerialName("Signer")
    Signer,
    @SerialName("Viewer")
    Viewer,
    @SerialName("Unknown")
    Unknown,
}

/** Permission levels for participants */
@Serializable
enum class PermissionLevel {
    @SerialName("Read")
    Read,
    @SerialName("Sign")
    Sign,
    @SerialName("Admin")
    Admin,
}

/** Signature record - uses LWW based on created_at timestamp */
@Serializable
data class SignatureRecord(
    val id: ULong,
    val name: String,
    @SerialName("blob_id") val blobId: ContractBytes,
    val size: ULong,
    @SerialName("created_at") val createdAt: ULong,
)

/**
 * One signature: the signer (the entry's owner stamp) took the version at
 * `base_hash`, put their mark on it, and produced the version at `new_hash`,
 * stored as `pdf_blob_id`. Written once, so a signature can be neither
 * withdrawn nor edited, and the version it signed stays on record.
 */
@Serializable
data class SignedVersion(
    @SerialName("base_hash") val baseHash: String,
    @SerialName("new_hash") val newHash: String,
    @SerialName("pdf_blob_id") val pdfBlobId: ContractBytes,
    val size: ULong,
    @SerialName("signed_at") val signedAt: ULong,
)

/**
 * A document as uploaded. Written once: nobody, the uploader included, can
 * change it afterwards, and only an admin (a moderator of `documents`) can
 * remove it. The uploader is the entry's owner stamp.
 *
 * What signing changes is recorded beside it, one write-once
 * [`SignedVersion`] per signature, never by rewriting this.
 */
@Serializable
data class StoredDocument(
    val name: String,
    val hash: String,
    @SerialName("pdf_blob_id") val pdfBlobId: ContractBytes,
    val size: ULong,
    @SerialName("uploaded_at") val uploadedAt: ULong,
    /**
     * Who must sign it: every participant holding `Sign` or `Admin` when it
     * was uploaded. Fixed with the document, so completion is a fact about
     * the past — nobody who joins later reopens it.
     */
    @SerialName("required_signers") val requiredSigners: List<ContractBytes>,
    val embeddings: List<Float>? = null,
    @SerialName("extracted_text") val extractedText: String? = null,
    val chunks: List<DocumentChunk>? = null,
)

/**
 * Fixed-size bytes. An id with its own spelling (`UserId`, `BlobId`) is [Text] —
 * base58 or hex, exactly as the contract writes it — and a plain `[u8; N]` is
 * [Raw], an array of numbers. Decoding takes whichever arrives; encoding writes
 * the form this value holds.
 */
@Serializable(with = ContractBytesSerializer::class)
sealed class ContractBytes {
    data class Text(val value: String) : ContractBytes()

    data class Raw(val value: List<UByte>) : ContractBytes()

    /** The text form, if that is what this holds. */
    val text: String? get() = (this as? Text)?.value

    /** The array form, if that is what this holds. */
    val raw: List<UByte>? get() = (this as? Raw)?.value
}

internal object ContractBytesSerializer : KSerializer<ContractBytes> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: ContractBytes) {
        val element = when (value) {
            is ContractBytes.Text -> JsonPrimitive(value.value)
            is ContractBytes.Raw -> JsonArray(value.value.map { JsonPrimitive(it.toInt()) })
        }
        (encoder as JsonEncoder).encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): ContractBytes {
        val element = (decoder as JsonDecoder).decodeJsonElement()
        return if (element is JsonPrimitive && element.isString) {
            ContractBytes.Text(element.content)
        } else {
            ContractBytes.Raw(element.jsonArray.map { it.jsonPrimitive.content.toInt().toUByte() })
        }
    }
}
